import{buildMissile}from'./equipment.js?v=balance-8';
import{groundHeight}from'./world.js?v=balance-8';
import{CrashSequence}from'./crash.js?v=balance-8';
const B=globalThis.BABYLON,V=B.Vector3,clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const HIT_PAY={aircraft:300,bird:90,scenery:100,cable:150,terrain:35,water:0};
export function segmentBoxHit(a,b,c,pad=0){let lo=0,hi=1;for(const[k,min,max]of[['x',c.x-c.w/2-pad,c.x+c.w/2+pad],['y',(c.bottom??0)-pad,c.y+pad],['z',c.z-c.d/2-pad,c.z+c.d/2+pad]]){const d=b[k]-a[k];if(Math.abs(d)<1e-9){if(a[k]<min||a[k]>max)return null;}else{let p=(min-a[k])/d,q=(max-a[k])/d;if(p>q)[p,q]=[q,p];lo=Math.max(lo,p);hi=Math.min(hi,q);if(lo>hi)return null;}}return lo;}
export function segmentSphereHit(a,b,c,r){const d=b.subtract(a),m=a.subtract(c),aa=d.lengthSquared(),cc=m.lengthSquared()-r*r;if(cc<=0)return 0;if(aa<1e-9)return null;const bb=V.Dot(m,d),disc=bb*bb-aa*cc;if(disc<0)return null;const t=(-bb-Math.sqrt(disc))/aa;return t>=0&&t<=1?t:null;}
export function terrainHit(a,b){const n=Math.max(1,Math.ceil(V.Distance(a,b)/3));let last=0;for(let i=0;i<=n;i++){const t=i/n,p=V.Lerp(a,b,t),h=groundHeight(p.x,p.z);if(p.y<=Math.max(0,h)+.15){let lo=last,hi=t;for(let j=0;j<8;j++){const mid=(lo+hi)/2,q=V.Lerp(a,b,mid);if(q.y<=Math.max(0,groundHeight(q.x,q.z))+.15)hi=mid;else lo=mid;}const point=V.Lerp(a,b,hi),height=groundHeight(point.x,point.z);point.y=Math.max(0,height);return{t:hi,point,kind:height<0?'water':'terrain'};}last=t;}return null;}
export function segmentContact(p1,q1,p2,q2){const d1=q1.subtract(p1),d2=q2.subtract(p2),r=p1.subtract(p2),a=V.Dot(d1,d1),e=V.Dot(d2,d2),f=V.Dot(d2,r);let s=0,t=0;if(a<=1e-8&&e<=1e-8)return{t:0,u:0,distanceSq:V.DistanceSquared(p1,p2)};if(a<=1e-8)t=clamp(f/e,0,1);else{const c=V.Dot(d1,r);if(e<=1e-8)s=clamp(-c/a,0,1);else{const b=V.Dot(d1,d2),denom=a*e-b*b;s=denom?clamp((b*f-c*e)/denom,0,1):0;t=(b*s+f)/e;if(t<0){t=0;s=clamp(-c/a,0,1);}else if(t>1){t=1;s=clamp((b-c)/a,0,1);}}}return{t:s,u:t,distanceSq:V.DistanceSquared(p1.add(d1.scale(s)),p2.add(d2.scale(t)))};}
export function staticHit(a,b,world,pad=.2){let best=terrainHit(a,b);for(const c of world.colliders){const t=segmentBoxHit(a,b,c,pad);if(t!==null&&(!best||t<best.t))best={t,kind:'scenery',target:c,point:V.Lerp(a,b,t)};}for(const cable of world.cables){const contact=segmentContact(a,b,cable.a,cable.b);if(contact.distanceSq>(pad+.28)**2)continue;const t=contact.t;if(!best||t<best.t)best={t,kind:'cable',target:cable,point:V.Lerp(cable.a,cable.b,contact.u)};}return best;}
function targetVolumes(target){const yaw=target.root.rotation.y,f=new V(Math.sin(yaw),0,Math.cos(yaw)),r=new V(Math.cos(yaw),0,-Math.sin(yaw)),volumes=[{offset:V.Zero(),radius:target.radius}];if(target.kind==='aircraft'){const length=target.def.length||10;for(const s of[-1,1]){volumes.push({offset:f.scale(s*length*.3),radius:target.def.airship?6:target.radius*.65});if(!target.def.airship)for(const t of[.18,.35,.47])volumes.push({offset:r.scale(s*target.def.span*t),radius:Math.max(.65,length*.035)});}}return volumes;}
export function movingHit(a,b,items){let best=null;for(const target of items){if(target.root.isDisposed())continue;const relA=a.subtract(target.previous||target.root.position),relB=b.subtract(target.root.position);for(const volume of targetVolumes(target)){const t=segmentSphereHit(relA,relB,volume.offset,volume.radius+.25);if(t!==null&&(!best||t<best.t))best={t,kind:target.kind,target,point:V.Lerp(a,b,t)};}}return best;}
export function turnToward(direction,desired,maxAngle){const dot=clamp(V.Dot(direction,desired),-1,1),angle=Math.acos(dot);if(angle<=maxAngle)return desired.clone();let axis=V.Cross(direction,desired);if(axis.lengthSquared()<1e-10)axis=V.Cross(direction,Math.abs(direction.y)<.9?V.Up():V.Right());axis.normalize();return V.TransformNormal(direction,B.Matrix.RotationAxis(axis,maxAngle)).normalize();}
export function missileOrientation(d){return B.Quaternion.RotationYawPitchRoll(Math.atan2(d.x,d.z),-Math.asin(clamp(d.y,-1,1)),0);}
export class MissileSystem{
 constructor(scene,world,traffic,effects,audio,onHit=()=>{}){this.scene=scene;this.world=world;this.traffic=traffic;this.effects=effects;this.audio=audio;this.onHit=onHit;this.missiles=[];this.blasts=[];this.cooldown=0;this.target=null;this.lockProgress=0;this.locked=false;this.ammo=0;this.weapon=null;this.missileId=0;this.sensorClock=0;this.visible=false;this.lost=0;}
 reset(plane,weapon){this.clear();this.plane=plane;this.weapon=weapon||null;this.ammo=weapon?.ammo||0;this.spent=0;this.cooldown=0;this.sensorClock=0;this.lost=0;}
 clear(){for(const m of this.missiles)m.part.node.dispose(false,false);for(const b of this.blasts)b.clear();this.missiles=[];this.blasts=[];this.ammo=0;this.spent=0;this.weapon=null;this.plane=null;this.cooldown=0;this.releaseTarget();}
 reload(){if(!this.weapon||!this.plane)return 0;const restored=this.weapon.ammo-this.ammo;if(restored<=0)return 0;this.ammo=this.weapon.ammo;this.spent=0;for(const part of this.plane.missileRounds||[]){part.spent=false;part.node.setEnabled(true);}return restored;}
 releaseTarget(){this.target=null;this.lockProgress=0;this.locked=false;this.visible=false;}
 candidates(flight){if(!this.weapon)return[];const{f}=flight.axes(),range=this.weapon.range+flight.speed*2;return this.traffic.items.map(target=>{const offset=target.root.position.subtract(flight.position),distance=offset.length(),alignment=V.Dot(offset.scale(1/Math.max(.01,distance)),f);return{target,distance,alignment};}).filter(v=>v.distance<range&&v.distance>12&&v.alignment>Math.cos(.48)).sort((a,b)=>b.alignment-a.alignment||a.distance-b.distance);}
 hasLineOfSight(flight,target){const a=flight.position,b=target.root.position;if(terrainHit(a,b))return false;for(const c of this.world.colliders)if(segmentBoxHit(a,b,c)!==null)return false;return true;}
 selectTarget(flight){if(!this.weapon)return false;const candidates=this.candidates(flight).filter(c=>this.hasLineOfSight(flight,c.target));if(!candidates.length){this.releaseTarget();return false;}const i=candidates.findIndex(c=>c.target===this.target);if(i===candidates.length-1){this.releaseTarget();return false;}this.target=candidates[i+1].target;this.lockProgress=0;this.locked=false;this.lost=0;this.sensorClock=.2;return true;}
 updateSensor(dt,flight){if(!this.weapon||!this.target)return;if(!this.traffic.items.includes(this.target)||this.target.root.isDisposed()){this.releaseTarget();return;}const offset=this.target.root.position.subtract(flight.position),distance=offset.length(),alignment=V.Dot(offset.scale(1/Math.max(.1,distance)),flight.axes().f);if(distance>this.weapon.range+flight.speed*2||alignment<Math.cos(.8)){this.releaseTarget();return;}this.sensorClock+=dt;if(this.sensorClock>=.1){this.visible=this.hasLineOfSight(flight,this.target);this.sensorClock=0;}if(!this.visible){this.locked=false;this.lockProgress=0;this.lost+=dt;if(this.lost>.5)this.releaseTarget();return;}this.lost=0;this.lockProgress=Math.min(1,this.lockProgress+dt/this.weapon.lockTime);this.locked=this.lockProgress>=1;}
 fire(flight){if(!this.weapon||this.ammo<=0||this.cooldown>0||flight.crashed||flight.landed)return false;const carried=this.plane.missileRounds?.[this.spent],origin=carried?carried.node.getAbsolutePosition().clone():flight.position.add(flight.axes().u.scale(-.9));if(carried){carried.spent=true;carried.node.setEnabled(false);}const part=buildMissile(this.scene,this.plane.type,null),f=flight.axes().f,velocity=f.scale(Math.max(60,V.Dot(flight.velocity,f)+60));part.node.position.copyFrom(origin);part.node.rotationQuaternion=missileOrientation(velocity.normalizeToNew());const target=this.locked&&this.visible&&this.traffic.items.includes(this.target)&&this.hasLineOfSight(flight,this.target)?this.target:null;this.missiles.push({id:++this.missileId,part,position:origin,velocity,direction:velocity.normalizeToNew(),target,age:0,trail:0,maxSpeed:Math.max(this.weapon.speed,flight.speed+500)});this.ammo--;this.spent++;this.cooldown=this.weapon.cooldown;this.audio.missileLaunch?.();return true;}
 impact(hit,missile){const blast=new CrashSequence(this.scene,this.effects,this.world,this.traffic);blast.impactPoint.copyFrom(hit.point);blast.center.copyFrom(hit.point);blast.fuel=65;blast.time=0;blast.energy=missile.velocity.length();if(['scenery','cable','aircraft','bird'].includes(hit.kind))blast.breakTarget(hit,missile.velocity.scale(.15));const surface=groundHeight(hit.point.x,hit.point.z),nearGround=hit.point.y<=Math.max(0,surface)+12;if(nearGround&&surface>=0)blast.makeCrater(new V(hit.point.x,surface,hit.point.z),hit.kind==='terrain'?11:9,hit.kind==='terrain'?5:3,missile.velocity.scale(.15));this.effects.explosion(hit.point,{fuel:65,energy:350,ground:nearGround,water:hit.kind==='water'});this.audio.impact?.(true);blast.life=9;this.blasts.push(blast);if(this.blasts.length>8)this.blasts.shift().clear();const g=this.world.globalPosition(hit.point),id=hit.target?.damageId||hit.target?.owner?.id||hit.kind+'/'+Math.floor(g.x/20)+'/'+Math.floor(g.z/20);this.onHit({id,kind:hit.kind,value:HIT_PAY[hit.kind]||0,name:hit.target?.def?.name||hit.target?.owner?.name||hit.kind});if(hit.target===this.target)this.releaseTarget();}
 update(dt,flight,active=true){this.cooldown=Math.max(0,this.cooldown-dt);if(active)this.updateSensor(dt,flight);for(const m of [...this.missiles]){m.age+=dt;if(m.age>this.weapon.life){m.part.node.dispose(false,false);this.missiles.splice(this.missiles.indexOf(m),1);continue;}const a=m.position.clone();if(m.target&&(!this.traffic.items.includes(m.target)||m.target.root.isDisposed()))m.target=null;if(m.target&&m.age>.16){const range=V.Distance(m.position,m.target.root.position),lead=Math.min(2.5,range/Math.max(100,m.velocity.length())),aim=m.target.root.position.add(m.target.velocity.scale(lead)).subtract(m.position).normalize();m.direction=turnToward(m.direction,aim,this.weapon.turnRate*dt);}const speed=Math.min(m.maxSpeed,m.velocity.length()+dt*380);m.velocity=m.direction.scale(speed);if(m.age<.14)m.velocity.y-=2;const b=a.add(m.velocity.scale(dt));let hit=staticHit(a,b,this.world),sky=movingHit(a,b,this.traffic.items);if(sky&&(!hit||sky.t<hit.t))hit=sky;if(hit){this.impact(hit,m);m.part.node.dispose(false,false);this.missiles.splice(this.missiles.indexOf(m),1);continue;}m.position.copyFrom(b);m.part.node.position.copyFrom(b);m.part.node.rotationQuaternion=missileOrientation(m.direction);m.trail+=dt;while(m.trail>.018){m.trail-=.018;const pos=b.subtract(m.direction.scale(1.1));this.effects.emit(pos,m.velocity.scale(.12).subtract(m.direction.scale(16)),'blue',.2,.18);this.effects.emit(pos,m.velocity.scale(.035).add(new V(0,.6,0)),'smoke',.22,1.6);}}
 for(const blast of [...this.blasts]){blast.update(dt);blast.life-=dt;if(blast.life<=0){blast.clear();this.blasts.splice(this.blasts.indexOf(blast),1);}}}
 stopProjectiles(){for(const m of this.missiles)m.part.node.dispose(false,false);this.missiles=[];this.releaseTarget();}
 rebase(dx,dz){for(const m of this.missiles){m.position.x-=dx;m.position.z-=dz;m.part.node.position.copyFrom(m.position);}for(const b of this.blasts){b.impactPoint.x-=dx;b.impactPoint.z-=dz;b.center.x-=dx;b.center.z-=dz;for(const p of b.pieces){p.mesh.position.x-=dx;p.mesh.position.z-=dz;}}}
}
